import * as React from "react"
import { cn } from "@/lib/utils"

interface GlitchTextProps extends React.HTMLAttributes<HTMLDivElement> {
  text?: string
}

export function GlitchText({ 
  className, 
  text = "404",
  ...props 
}: GlitchTextProps) {
  return (
    <div 
      className={cn(
        "relative font-display text-[110px] font-black leading-none",
        className
      )}
      style={{
        color: "var(--accent)",
        textShadow: "3px 0 var(--accent-2), -3px 0 #ffff00",
        animation: "gp-glitch 3s ease-in-out infinite",
      }}
      {...props}
    >
      <span className="relative z-10">{text}</span>
      <span 
        className="absolute top-0 left-0 pointer-events-none"
        style={{
          color: "var(--accent-2)",
          clipPath: "inset(20% 0 60% 0)",
          animation: "gp-glitch-offset 2s ease-in-out infinite",
        }}
        aria-hidden="true"
      >
        {text}
      </span>
      <span 
        className="absolute top-0 left-0 pointer-events-none"
        style={{
          color: "#ffff00",
          clipPath: "inset(60% 0 10% 0)",
          animation: "gp-glitch-offset 3s ease-in-out infinite reverse",
        }}
        aria-hidden="true"
      >
        {text}
      </span>
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

interface GlitchLabelProps extends React.HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode
}

export function GlitchLabel({ className, children, ...props }: GlitchLabelProps) {
  return (
    <div 
      className={cn(
        "font-mono text-[11px] tracking-[0.2em] uppercase",
        className
      )}
      style={{
        color: "var(--fg-dim)",
      }}
      {...props}
    >
      {children}
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

interface GlitchStageProps extends React.HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode
}

export function GlitchStage({ className, children, ...props }: GlitchStageProps) {
  return (
    <div 
      className={cn(
        "relative z-[1] flex flex-col items-center gap-3.5 text-center",
        className
      )}
      {...props}
    >
      {children}
    </div>
  )
}

/* Glitchpage theme effects */
@keyframes gp-glitch {
  0%, 90%, 100% { transform: translate(0); }
  92% { transform: translate(-3px, 2px); }
  94% { transform: translate(3px, -1px); }
  96% { transform: translate(-2px, -2px); }
  98% { transform: translate(1px, 1px); }
}

@keyframes gp-glitch-offset {
  0%, 80%, 100% { transform: translate(0); }
  85% { transform: translate(-8px, 5px); }
  90% { transform: translate(5px, -3px); }
  95% { transform: translate(-4px, 4px); }
}
